#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll modPow(ll base, ll exp, ll mod) {
    ll result = 1 % mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ll a, b, mod;
    scanf("%lld%lld%lld", &a, &b, &mod);

    if (mod <= 0 || b >= mod - 1) {
        printf("2\n");
        return 0;
    }

    ll multiplier = modPow(10, 10, mod);
    ll period = mod / std::gcd(multiplier, mod);
    ll limit = min(a, period - 1);
    ll residue = 0;

    for (ll n = 0; n <= limit; ++n) {
        ll required = (mod - residue) % mod;
        if (required > b) {
            printf("1 %09lld\n", n);
            return 0;
        }
        residue += multiplier;
        if (residue >= mod) residue -= mod;
    }

    printf("2\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    int64 a, b, mod;
    scanf("%lld%lld%lld", &a, &b, &mod);

    int64 power = 1 % mod;
    for (int i = 0; i < 10; ++i)
        power = power * 10 % mod;

    int64 period = mod / std::gcd(power, mod);
    int64 limit = min(a, period - 1);
    int64 remainder = 0;
    int64 answer = -1;

    for (int64 n = 0; n <= limit; ++n) {
        if (remainder != 0 && mod - remainder > b) {
            answer = n;
            break;
        }
        remainder = (remainder + power) % mod;
    }

    if (answer == -1) {
        printf("2\n");
    } else {
        printf("1 %09lld\n", answer);
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 floorSum(int64 n, int64 m, int64 a, int64 b) {
    i128 ans = 0;

    while (true) {
        if (a >= m) {
            ans += (i128)(n - 1) * n * (a / m) / 2;
            a %= m;
        }
        if (b >= m) {
            ans += (i128)n * (b / m);
            b %= m;
        }

        i128 y = (i128)a * n + b;
        if (y < m) break;

        n = (int64)(y / m);
        b = (int64)(y % m);
        swap(m, a);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 A, B, mod;
    cin >> A >> B >> mod;

    if (B >= mod - 1) {
        cout << "2\n";
        return 0;
    }

    int64 power10 = 1 % mod;
    for (int i = 0; i < 10; ++i)
        power10 = (i128)power10 * 10 % mod;

    int64 coefficient = (mod - power10) % mod;
    int64 threshold = B + 1;

    auto countValid = [&](int64 x) -> i128 {
        int64 n = x + 1;
        return floorSum(n, mod, coefficient, mod - threshold)
             - floorSum(n, mod, coefficient, 0);
    };

    if (countValid(A) == 0) {
        cout << "2\n";
        return 0;
    }

    int64 low = 0, high = A;
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (countValid(mid) > 0)
            high = mid;
        else
            low = mid + 1;
    }

    cout << "1 " << setw(9) << setfill('0') << low << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int a[9];
int mod;
ll boundB, power10;
vector<unsigned char> memo;
signed char tightMemo[9];

unsigned getState(int i, int k) {
    size_t index = static_cast<size_t>(i) * mod + k;
    return (memo[index >> 2] >> ((index & 3) * 2)) & 3U;
}

void setState(int i, int k, unsigned value) {
    size_t index = static_cast<size_t>(i) * mod + k;
    unsigned shift = (index & 3) * 2;
    memo[index >> 2] =
        (memo[index >> 2] & ~(3U << shift)) | (value << shift);
}

bool dp(int i, bool smaller, int remainder) {
    if (i == 9) {
        ll value = static_cast<ll>(remainder) * power10 % mod;
        ll required = value == 0 ? 0 : mod - value;
        return required > boundB;
    }

    if (smaller) {
        unsigned state = getState(i, remainder);
        if (state) return state == 2;
    } else if (tightMemo[i] != -1) {
        return tightMemo[i];
    }

    int limit = smaller ? 9 : a[i];
    bool result = false;

    for (int digit = 0; digit <= limit; ++digit) {
        int nextRemainder = (remainder * 10LL + digit) % mod;
        if (dp(i + 1, smaller || digit < a[i], nextRemainder)) {
            result = true;
            break;
        }
    }

    if (smaller)
        setState(i, remainder, result ? 2 : 1);
    else
        tightMemo[i] = result;

    return result;
}

void constructAnswer(int i, bool smaller, int remainder) {
    if (i == 9) return;

    int limit = smaller ? 9 : a[i];
    for (int digit = 0; digit <= limit; ++digit) {
        int nextRemainder = (remainder * 10LL + digit) % mod;
        bool nextSmaller = smaller || digit < a[i];

        if (dp(i + 1, nextSmaller, nextRemainder)) {
            cout << digit;
            constructAnswer(i + 1, nextSmaller, nextRemainder);
            return;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int x;
    cin >> x;
    for (int i = 8; i >= 0; --i) {
        a[i] = x % 10;
        x /= 10;
    }

    cin >> x;
    int b[9];
    for (int i = 8; i >= 0; --i) {
        b[i] = x % 10;
        x /= 10;
    }

    boundB = 0;
    for (int digit : b) boundB = boundB * 10 + digit;

    cin >> mod;

    if (mod <= 0 || boundB >= mod - 1LL) {
        cout << "2\n";
        return 0;
    }

    power10 = 1 % mod;
    for (int i = 0; i < 10; ++i)
        power10 = power10 * 10 % mod;

    memo.assign((static_cast<size_t>(9) * mod + 3) / 4, 0);
    memset(tightMemo, -1, sizeof(tightMemo));

    if (dp(0, false, 0)) {
        cout << "1 ";
        constructAnswer(0, false, 0);
        cout << '\n';
    } else {
        cout << "2\n";
    }

    return 0;
}

